static int sdio_generate_slave_intr(uint8_t intr_no)
{
	uint8_t intr_mask = EH_SET_BIT(intr_no + ESP_SDIO_CONF_OFFSET);

	if (intr_no >= EH_SET_BIT(ESP_MAX_HOST_INTERRUPT)) {
		ESP_LOGE(TAG,"Invalid slave interrupt number");
