  memset(swbuf, 0x5a, sizeof(swbuf));
  sw_ret60 = sdio_io_rw_extended(sdio, false, 1, 0x1f800u - 60u, true,
                                 swbuf, 60, 0);

  syslog(LOG_INFO, "%s: sweep summary max_ok=%d r4=%d r20=%d r60=%d\n",
         HOSTED_TAG, sw_max, sw_ret4, sw_ret20, sw_ret60);
}

