// Ensure the PSRAM/MSPI core clock gate is open before touching the MMU.
//
// HP_SYS_CLKRST_PERI_CLK_CTRL00 bit15 (PSRAM_CORE_CLK_EN) resets to 1, but
// it has been observed cleared on this board after a WDT reset -- the clock
// domain does not get re-initialised, so the state survives resets until
// power is removed.  With the gate shut the whole MSPI/PSRAM register block
// stops answering and the very next MMU write (mmu_hal_unmap_all, below)
// faults with Store/AMO access fault at 0x5008E380: the board looks dead
// and only a debugger poke (mww 0x500E6030) can revive it.
//
// Writing the bit back is one register access, is harmless when the bit is
// already set, and it has to happen here: no code of ours runs before this
// function, so a guard placed later cannot prevent the crash.

REG_SET_BIT(HP_SYS_CLKRST_PERI_CLK_CTRL00_REG,
            HP_SYS_CLKRST_REG_PSRAM_CORE_CLK_EN);

//reset MMU table first
mmu_hal_unmap_all();

// Writing the bit back is one register access, is harmless when the bit is
// already set, and it has to happen here: no code of ours runs before this
// function, so a guard placed later cannot prevent the crash.  The access
// is spelled out as a raw register poke on purpose -- the bootloader link
// does not pull in the clock HAL headers, and one extra include in a
// third-party tree is a bigger diff than the write itself.

*(volatile uint32_t *)0x500e6030u |= (1u << 15);   /* PSRAM_CORE_CLK_EN */

