void mmu_hal_unmap_all(void)
{
    // Open the PSRAM/MSPI core clock gate before any MMU write.
    //
    // HP_SYS_CLKRST_PERI_CLK_CTRL00 bit15 (PSRAM_CORE_CLK_EN) resets to 1, but
    // it has been seen cleared on this board after a WDT reset -- that domain is
    // not re-initialised, so the state survives resets until power is removed.
    // With the gate shut the MSPI/PSRAM register window stops answering and the
    // next write to SPI_MEM_S_MMU_ITEM_INDEX_REG (0x5008E380) faults with a
    // Store/AMO access fault; the board then looks dead and only a debugger poke
    // revives it.
    //
    // The guard lives here rather than at a call site because several callers
    // unmap the MMU during early boot (the flash driver does it before
    // bootloader_utility runs), so this is the first point that covers all of
    // them.  Writing the bit is harmless when it is already set.

    *(volatile uint32_t *)0x500e6030u |= (1u << 15);   /* PSRAM_CORE_CLK_EN */

